import React from "react";
import useFetch from "./useFetch";

const Home = () => {
    const { data, loading, error } = useFetch("https://jsonplaceholder.typicode.com/todos");

    if (loading) {
        return <p>Loading...</p>;
    }

    if (error) {
        return <p>Error: {error.message}</p>;
    }

    return (
        <>
            {data &&
                data.map((item) => {
                    return <p key={item.id}>{item.title}</p>;
                })}
        </>
    );
};

export default Home;
